from pathlib import Path
import json
E=[]
def F(label,answer,kind='number',**kw): return dict(label=label,answer=answer,kind=kind,**kw)
def add(t,l,lesson,title,prompt,fields,solution,hints,**kw):
 n=sum(x['topic']==t and not x.get('exam') for x in E)+1
 E.append(dict(id=f't{t}-{n:02}',topic=t,level=l,lesson=lesson,title=title,prompt=prompt,fields=fields,solution=solution,hints=hints,**kw))
# N normal, M medio, G examen de grado. Los ejercicios son originales.
add(1,'N','1-1','Operar con conjuntos',r'$A=\{0,2,4,6\}$, $B=\{2,3,6\}$. Introduce los elementos de cada conjunto, separados por punto y coma.',[F('A ∩ B',[2,6],'set'),F('A ∖ B',[0,4],'set')],r'Los comunes son 2 y 6. Al quitar de A los que están en B quedan 0 y 4. El orden de escritura no cambia el conjunto.',['Busca primero los elementos comunes.','En A∖B no añadas ningún elemento de B.'])
add(1,'N','1-1','Contar sin enumerar',r'A tiene 4 elementos y B tiene 3. Calcula los cardinales.',[F('|A × B|',12),F('|𝒫(A)|',16)],r'Cada uno de los 4 elementos puede emparejarse con 3: $4\cdot3=12$. Un subconjunto decide incluir o no cada elemento: $2^4=16$.',['Producto cartesiano: multiplica.','Potencia: cada elemento tiene dos opciones.'])
add(1,'N','1-3','De binario a decimal',r'Convierte $(110101)_2$ a decimal.',[F('Valor decimal',53)],r'$32+16+4+1=53$. Las posiciones con cero no contribuyen.',['Escribe las potencias de 2 de derecha a izquierda.'])
add(1,'N','1-3','Fracción en binario',r'¿Qué número racional representa $(0.101)_2$?',[F('Fracción o decimal',0.625)],r'$2^{-1}+2^{-3}=1/2+1/8=5/8$.',['La primera posición tras la coma pesa 1/2.'])
add(1,'N','1-5','Conjugado y módulo',r'Para $z=3-4i$, calcula el conjugado y el módulo. Un complejo se introduce como «parte real; parte imaginaria».',[F('Conjugado',[3,4],'vector'),F('Módulo',5)],r'$\bar z=3+4i$ y $|z|=\sqrt{9+16}=5$.',['Conjugar cambia solo la parte imaginaria.'])
add(1,'N','1-6','Un ciclo de potencias',r'Calcula $i^{37}$. Introduce parte real y parte imaginaria.',[F('i³⁷',[0,1],'vector')],r'$37=4\cdot9+1$ y $i^4=1$, de modo que $i^{37}=i$.',['El ciclo de las potencias tiene longitud 4.'])
add(1,'M','1-2','Preimagen e inyectividad',r'Para $f:\mathbb R\to\mathbb R$, $f(x)=(x-1)^2$, encuentra $f^{-1}(\{9\})$. Decide si f es inyectiva.',[F('Preimagen',[-2,4],'set'),F('¿Inyectiva?','no','choice',options=['sí','no'])],r'$(x-1)^2=9$ implica x−1=±3, es decir x=−2 o x=4. Dos entradas distintas con la misma imagen refutan inyectividad.',['Despeja las dos raíces, no solo la positiva.'])
add(1,'M','1-3','Periodo racional',r'Expresa $0.\overline{27}$ como fracción irreducible. Se acepta la fracción o un decimal equivalente.',[F('Fracción irreducible (o su decimal)',3/11)],r'Si x=0,2727…, entonces 100x−x=27. Por tanto x=27/99=3/11, y 3/11=0,272727…',['Multiplica por 100 para alinear el periodo.'])
add(1,'M','1-4','Error relativo',r'Aproxima $2/3$ por 0,67. Da error absoluto y relativo como números, no porcentajes.',[F('Error absoluto',1/300),F('Error relativo',1/200)],r'$|67/100-2/3|=1/300$. Al dividir entre 2/3 resulta 1/200=0,005.',['Usa fracciones exactas antes de restar.'])
add(1,'M','1-4','Empate al par',r'Redondea los decimales exactos 4,265 y 4,275 a dos decimales, con empate al par.',[F('4,265 redondeado',4.26),F('4,275 redondeado',4.28)],r'Entre 4,26 y 4,27 se elige 4,26 porque 6 es par. Entre 4,27 y 4,28 se elige 4,28 porque 8 es par.',['Comprueba la paridad de la última cifra conservada.'])
add(1,'M','1-5','Dividir en ℂ',r'Calcula $(3+2i)/(1-i)$.',[F('Parte real; parte imaginaria',[0.5,2.5],'vector')],r'Multiplica por (1+i)/(1+i). El numerador es 1+5i y el denominador 2. Resultado: 1/2+(5/2)i.',['Usa el conjugado del denominador.'])
add(1,'M','1-6','Potencia en forma polar',r'Calcula $(1+i)^8$.',[F('Parte real; parte imaginaria',[16,0],'vector')],r'$1+i=\sqrt2e^{i\pi/4}$, luego la potencia es $16e^{2\pi i}=16$.',['Eleva el módulo y multiplica el argumento.'])
add(1,'G','1-3','Bases que terminan',r'Encuentra la menor base entera b≥2 en la que 1/12 tiene desarrollo finito. Justifica mediante factores primos.',[F('Base mínima',6)],r'12=2²·3. La base debe contener los primos 2 y 3, así que debe ser múltiplo de 6. La menor es 6 y $1/12=3/36=(0.03)_6$.',['El denominador debe dividir alguna potencia de b.'])
add(1,'G','1-6','Todas las raíces de −16',r'Para $z^4=-16$, determina el módulo común y los cuatro argumentos entre 0 y 2π, expresados como coeficientes de π.',[F('Módulo',2),F('Coeficientes de π',[0.25,0.75,1.25,1.75],'set')],r'$-16=16e^{i\pi}$. Las raíces son $2e^{i(\pi+2k\pi)/4}$ para k=0,1,2,3; sus argumentos son π/4,3π/4,5π/4,7π/4.',['Incluye las vueltas completas antes de dividir por 4.'])
add(1,'G','1-6','Multiplicidades',r'Para $p(z)=(z-1)^3(z^2+4)^2$, indica grado, número de raíces distintas y multiplicidad de 2i.',[F('Grado',7),F('Raíces distintas',3),F('Multiplicidad de 2i',2)],r'$z^2+4=(z-2i)(z+2i)$. Las raíces son 1 triple, 2i doble y −2i doble; 3+2+2=7.',['Factoriza el cuadrático sobre ℂ.'])
add(1,'G','1-2','Dominios que importan',r'$f:[0,\infty)\to[1,\infty)$, $f(x)=x^2+1$. ¿Es biyectiva? Calcula $f^{-1}(10)$ y justifica unicidad.',[F('¿Biyectiva?','sí','choice',options=['sí','no']),F('f⁻¹(10)',3)],r'Es estrictamente creciente en el dominio y para todo y≥1 existe la única entrada $\sqrt{y-1}\ge0$. Para y=10 resulta 3; −3 no pertenece al dominio.',['La restricción del dominio elimina una de las raíces.'])
add(1,'G','1-5','Una ecuación con conjugación',r'Resuelve $z+2\bar z=6-3i$ escribiendo z=a+bi.',[F('a; b',[2,3],'vector')],r'$z+2\bar z=3a-bi$. Igualar partes reales e imaginarias da 3a=6 y −b=−3, de donde z=2+3i.',['Trata a y b como incógnitas reales.'])
add(1,'G','1-4','Control de precisión',r'¿Cuántos decimales como mínimo garantizan error absoluto ≤0,0005 al redondear al más cercano? Justifica una cota válida para cualquier real.',[F('Decimales mínimos',3)],r'La cota es $\tfrac12 10^{-d}$. Con d=3 vale 0,0005. Con d=2 puede llegar a 0,005, así que no garantiza lo pedido.',['Piensa en la mitad de la separación entre dos representaciones consecutivas.'])
# TEMA II
add(2,'N','2-1','Subespacio o plano afín',r'Clasifica $S=\{(x,y):x-2y=0\}$ y $T=\{(x,y):x-2y=1\}$.',[F('¿S subespacio?','sí','choice',options=['sí','no']),F('¿T subespacio?','no','choice',options=['sí','no'])],r'S es el núcleo de una ecuación homogénea, cerrado para combinaciones. T no contiene (0,0).',['Comprueba primero el cero.'])
add(2,'N','2-2','Dimensión de polinomios',r'En el espacio real de polinomios de grado a lo sumo 4, indica dimensión y coordenadas de $2-t+3t^4$ en $(1,t,t^2,t^3,t^4)$.',[F('Dimensión',5),F('Coordenadas',[2,-1,0,0,3],'vector')],r'Hay cinco potencias desde 0 hasta 4. Los coeficientes de t² y t³ son cero.',['No omitas el término constante.'])
add(2,'N','2-3','Contar un tensor',r'Un tensor tiene formato 3×4×2. Se permutan los ejes al orden (3,1,2).',[F('Número de entradas',24),F('Nuevo formato',[2,3,4],'vector')],r'3·4·2=24. Los nuevos ejes toman longitudes 2,3,4; ninguna entrada desaparece.',['Formato y contenido son cosas distintas.'])
add(2,'N','2-4','Producto rectangular',r'$A=\begin{pmatrix}1&2&0\\0&-1&3\end{pmatrix}$, $b=(2,1,-1)^{\mathsf T}$. Calcula Ab.',[F('Ab',[4,-4],'vector')],r'Primera fila: 2+2=4. Segunda: −1−3=−4. El resultado tiene dos componentes.',['Una componente por fila.'])
add(2,'N','2-6','Norma y distancia',r'Para u=(3,4), v=(3,0), calcula norma de u y distancia entre u y v.',[F('‖u‖',5),F('d(u,v)',4)],r'‖u‖=√(9+16)=5. La diferencia u−v=(0,4) tiene norma 4.',['Resta los vectores antes de medir distancia.'])
add(2,'N','2-5','Inversa 2×2',r'Calcula la inversa de $\begin{pmatrix}2&1\\1&1\end{pmatrix}$. Introduce una fila por línea y componentes separadas por punto y coma.',[F('Matriz inversa',[[1,-1],[-1,2]],'matrix')],r'El determinante es 1. Intercambia las entradas diagonales y cambia los signos de las otras: [[1,−1],[−1,2]].',['Comprueba el resultado multiplicando.'])
add(2,'M','2-2','Una base diferente también vale',r'Da dos vectores que formen una base de $S=\{(x,y,z):x+y-z=0\}$. Escribe cada vector en una fila.',[F('Base de S',[[1,0,1],[0,1,1]],'basis')],r'La parametrización (x,y,x+y)=x(1,0,1)+y(0,1,1) proporciona una base. Se aceptan dos vectores independientes cualesquiera que generen el mismo plano.',['Despeja z y usa x e y como parámetros.'])
add(2,'M','2-5','Cambiar coordenadas',r'B=((1,1),(1,−1)). En la notación compacta cada par es uno de los vectores de la base y se coloca como columna. Calcula las coordenadas de x=(5,1) en B.',[F('[x]B',[3,2],'vector')],r'x=a·b₁+b·b₂ da a+b=5 y a−b=1. Sumando da a=3 y b=2.',['Escribe x=a·b₁+b·b₂.'])
add(2,'M','2-4','No conmutan',r'$A=\begin{pmatrix}1&1\\0&1\end{pmatrix}$, $B=\begin{pmatrix}1&0\\2&1\end{pmatrix}$. Calcula AB−BA.',[F('Conmutador',[[2,0],[0,-2]],'matrix')],r'AB=[[3,1],[2,1]] y BA=[[1,1],[2,3]]. Al restar queda diag(2,−2).',['Calcula ambos productos completos.'])
add(2,'M','2-6','Producto hermítico',r'u=(1,i), v=(i,1). Calcula u*v con la convención del curso. Un complejo se introduce como «parte real; parte imaginaria».',[F('Parte real; parte imaginaria',[0,0],'vector')],r'u*=(1,−i), de modo que u*v=i−i=0. Son ortogonales en ℂ².',['Conjuga la primera entrada.'])
add(2,'M','2-7','Un residuo de Gram–Schmidt',r'Usa u=(1,2,0) y v=(2,0,1). Obtén el residuo de v tras quitar su proyección sobre u, sin normalizar.',[F('Residuo',[8/5,-4/5,1],'vector')],r'El coeficiente es (uᵀv)/(uᵀu)=2/5. Resta (2/5)(1,2,0) de v y obtén (8/5,−4/5,1).',['No olvides dividir por uᵀu si u no es unitario.'])
add(2,'M','2-8','Proyectar sobre una recta',r'Proyecta b=(4,2,1) sobre span{(1,0,1)} y calcula la distancia.',[F('Proyección',[2.5,0,2.5],'vector'),F('Distancia',(8.5)**0.5)],r'El coeficiente es 5/2. El residuo (3/2,2,−3/2) tiene norma $\sqrt{17/2}$.',['La distancia es la norma del residuo.'])
add(2,'G','2-2','Dependencia con parámetro',r'Las columnas de $B_a=\begin{pmatrix}1&1&0\\0&a&1\\1&1&1\end{pmatrix}$ forman una base salvo para qué valor de a? En ese valor, da el rango.',[F('Valor excepcional',0),F('Rango excepcional',2)],r'Resta la fila 1 a la 3: queda (0,0,1). El determinante es a. Para a=0, las dos primeras columnas coinciden y la tercera es independiente: rango 2.',['Busca cuándo el determinante se anula.'])
add(2,'G','2-1','Suma e intersección',r'U=span{e₁,e₂} y W=span{e₂,e₃} en ℝ³. Da una base de U∩W y la dimensión de U+W.',[F('Base de la intersección',[[0,1,0]],'basis'),F('Dimensión de la suma',3)],r'La intersección solo tiene dirección e₂. La fórmula de dimensiones da 2+2−1=3 y la suma es ℝ³.',['Un vector común debe tener tercera y primera componentes cero.'])
add(2,'G','2-8','Matriz de una proyección',r'Construye la matriz de proyección ortogonal sobre el plano x+y+z=0.',[F('P',[[2/3,-1/3,-1/3],[-1/3,2/3,-1/3],[-1/3,-1/3,2/3]],'matrix')],r'El normal n=(1,1,1) tiene nᵀn=3. La proyección sobre el plano es $I-nn^{\mathsf T}/3$. Es simétrica, idempotente y anula n.',['Proyecta sobre el normal y resta de la identidad.'])
add(2,'G','2-5','Orientar el cambio',r'B=((1,1),(1,−1)), C=((1,0),(1,1)). En la notación compacta cada par entre paréntesis es uno de los vectores de la base, y esos vectores se colocan como COLUMNAS. Da la matriz que transforma coordenadas en B a coordenadas en C.',[F('C⁻¹B',[[0,2],[1,-1]],'matrix')],r'Las columnas de C son (1,0) y (1,1), así que C=[[1,1],[0,1]] y C⁻¹=[[1,−1],[0,1]]. Multiplica C⁻¹B: [[0,2],[1,−1]].',['Pasa primero a canónicas y luego a C.'])
add(2,'G','2-7','Detectar dependencia',r'Gram–Schmidt se aplica a (1,0,1), (2,0,2), (0,1,0), descartando residuos cero. ¿Cuántos vectores retiene? Da una base del complemento ortogonal de su generado.',[F('Vectores retenidos',2),F('Base del complemento',[[1,0,-1]],'basis')],r'El segundo vector es el doble del primero y no aporta dirección. Ser ortogonal al primero exige x+z=0 y al tercero y=0. El complemento es span{(1,0,−1)}.',['Identifica el vector redundante antes de calcular.'])
add(2,'G','2-3','Normal no significa simétrica',r'$R=\begin{pmatrix}0&-1\\1&0\end{pmatrix}$. Decide si es normal, simétrica y ortogonal sobre ℝ.',[F('Normal','sí','choice',options=['sí','no']),F('Simétrica','no','choice',options=['sí','no']),F('Ortogonal','sí','choice',options=['sí','no'])],r'RᵀR=RRᵀ=I: es ortogonal y normal. Rᵀ=−R≠R, luego no es simétrica.',['Calcula RᵀR y compara R con Rᵀ.'])
# TEMA III
add(3,'N','3-1','Matriz de una aplicación',r'f(x,y)=(x−y,2x+y,3y). Escribe su matriz canónica.',[F('Matriz 3×2',[[1,-1],[2,1],[0,3]],'matrix')],r'f(e₁)=(1,2,0), f(e₂)=(−1,1,3); son las columnas.',['Evalúa en los dos vectores canónicos.'])
add(3,'N','3-1','Linealidad',r'¿Es lineal f(x,y)=(x+y,xy)?',[F('Respuesta','no','choice',options=['sí','no'])],r'f(2,2)=(4,4), pero 2f(1,1)=(4,2). Falla homogeneidad aunque f(0)=0.',['Busca un contraejemplo de homogeneidad.'])
add(3,'N','3-2','Determinante triangular',r'Una triangular 4×4 tiene diagonal (2,−1,3,4). Calcula su determinante.',[F('Determinante',-24)],r'Producto de la diagonal: 2·(−1)·3·4=−24.',['No necesitas las entradas fuera de la diagonal.'])
add(3,'N','3-3','Rango y nulidad',r'A es 4×7 y tiene rango 3. Calcula las dimensiones de ker A y ker A*.',[F('dim ker A',4),F('dim ker A*',1)],r'La nulidad de A es 7−3=4; la de A* es 4−3=1.',['Cada núcleo se resta de la dimensión de su propio dominio.'])
add(3,'N','3-4','Una dirección propia',r'A=diag(2,5). Da un autovector para λ=5.',[F('Autovector',[0,1],'eigen',matrix=[[2,0],[0,5]],eigenvalue=5)],r'Los vectores (0,t), t≠0, cumplen Av=5v. Cualquier múltiplo no nulo es válido.',['Resuelve (A−5I)v=0.'])
add(3,'N','3-5','Matriz de una forma',r'Escribe la matriz simétrica de q(x,y)=3x²+6xy+2y².',[F('Matriz',[[3,3],[3,2]],'matrix')],r'Las entradas diagonales son 3 y 2. Cada entrada cruzada es la mitad de 6, es decir 3.',['Los dos términos cruzados de xᵀSx se suman.'])
add(3,'M','3-2','Operaciones de filas',r'det A=−3. B se obtiene intercambiando dos filas de A y multiplicando otra fila por 4. Calcula det B.',[F('det B',12)],r'El intercambio cambia el signo: 3. Multiplicar una fila por 4 da 12.',['Lleva la cuenta de cada factor.'])
add(3,'M','3-3','Núcleo rectangular',r'A tiene filas (1,2,2) y (0,1,−1). Da una base de su núcleo.',[F('Base',[[-4,1,1]],'basis')],r'Resolve y=z y x=−2y−2z=−4z, de modo que las soluciones son t(−4,1,1).',['Usa z como variable libre.'])
add(3,'M','3-2','Área orientada',r'Un triángulo tiene vértices (1,1),(4,2),(2,5). Calcula su área.',[F('Área',5.5)],r'Las aristas son (3,1),(1,4), de determinante 12−1=11. El área del triángulo es 11/2.',['Resta el mismo vértice a los otros dos.'])
add(3,'M','3-4','Espectro simétrico',r'A=[[2,1],[1,2]]. Da el conjunto de autovalores.',[F('Autovalores',[1,3],'set')],r'det(A−λI)=(2−λ)²−1=(λ−1)(λ−3).',['Factoriza una diferencia de cuadrados.'])
add(3,'M','3-5','Evaluar una forma',r'Para S=[[2,1],[1,3]] y x=(1,−2), calcula xᵀSx.',[F('Valor',10)],r'2x²+2xy+3y²=2−4+12=10. También Sx=(0,−5), cuyo producto con x es 10.',['El coeficiente cruzado es 2, no 1.'])
add(3,'M','3-4','Núcleo generalizado',r'N=[[0,1,0],[0,0,1],[0,0,0]]. Da las dimensiones de ker N, ker N², ker N³.',[F('Dimensiones',[1,2,3],'vector')],r'N(x,y,z)=(y,z,0), N²(x,y,z)=(z,0,0), N³=0. Las dimensiones son 1,2,3.',['Escribe la acción de N sobre un vector genérico.'])
add(3,'G','3-3','Imagen y núcleo a la vez',r'f(x,y,z)=(x+y,y+z,x+2y+z). Da una base de la imagen y una del núcleo.',[F('Base imagen',[[1,0,1],[0,1,1]],'basis'),F('Base núcleo',[[-1,1,-1]],'basis')],r'La tercera componente de salida suma las dos primeras; la imagen es el plano c=a+b. El núcleo exige x=−y y z=−y. Rango 2 y nulidad 1.',['Observa una relación entre las componentes de salida.'])
add(3,'G','3-2','Determinante paramétrico',r'Aₜ=[[1,t,0],[t,1,0],[0,0,t−2]]. Da todos los valores t para los que es singular.',[F('Valores',[-1,1,2],'set')],r'Por bloques, det Aₜ=(1−t²)(t−2). Los ceros son −1,1,2; fuera de ellos es invertible.',['Separa el bloque 2×2 del escalar final.'])
add(3,'G','3-1','Cambiar la matriz de una aplicación',r'f tiene matriz A=diag(2,3) en canónicas. En B=((1,1),(1,−1)), calcula la matriz de f, usando B tanto en entrada como en salida.',[F('B⁻¹AB',[[2.5,-0.5],[-0.5,2.5]],'matrix')],r'B⁻¹=(1/2)B. Multiplica (1/2)BAB para obtener [[5/2,−1/2],[−1/2,5/2]]. Su traza 5 y determinante 6 coinciden con A.',['La transformación de un endomorfismo es por similitud.'])
add(3,'G','3-5','Clasificar con parámetro',r'qₐ(x,y)=x²+2axy+y². Para a=2, da un vector donde sea negativa y decide si es indefinida.',[F('Vector con q<0',[1,-1],'negative',matrix=[[1,2],[2,1]]),F('¿Indefinida?','sí','choice',options=['sí','no'])],r'q₂(1,−1)=−2 y q₂(1,0)=1. Al tomar ambos signos es indefinida. Por completación: (x+2y)²−3y².',['Busca primero x=−y.'])
add(3,'G','3-4','Multiplicidades distintas',r'A=[[4,1,0],[0,4,0],[0,0,4]]. Para λ=4, calcula multiplicidad algebraica, geométrica y dim ker(A−4I)².',[F('Algebraica',3),F('Geométrica',2),F('Núcleo del cuadrado',3)],r'El característico es (4−λ)³. A−4I solo conserva la segunda coordenada en la primera: rango 1, nulidad 2; su cuadrado es cero.',['No confundas la multiplicidad de la raíz con la dimensión del autoespacio.'])
add(3,'G','3-5','Congruencia explícita',r'Completa cuadrados en q=3x²+6xy+5y² usando u=x+y, v=y. Da su matriz en (u,v) y la inercia (positivos,negativos,nulos).',[F('Matriz',[[3,0],[0,2]],'matrix'),F('Inercia',[2,0,0],'vector')],r'Con x=u−v, y=v, resulta q=3u²+2v². El cambio es invertible y ambos coeficientes son positivos.',['Sustituye, expande y cancela el término uv.'])
# TEMA IV
add(4,'N','4-1','Sistema triangular',r'Resuelve 2x+y=5, 3y=3.',[F('x; y',[2,1],'vector')],r'Primero y=1; después 2x=4, así x=2.',['Empieza por la última ecuación.'])
add(4,'N','4-1','Compatibilidad',r'Un sistema tiene 5 incógnitas, rango A=3 y rango [A|b]=4. Clasifícalo.',[F('Tipo','incompatible','choice',options=['única solución','infinitas soluciones','incompatible'])],r'Los rangos distintos violan Rouché–Frobenius: no tiene solución.',['Compara rangos antes de contar variables libres.'])
add(4,'N','4-1','Variables libres',r'Un sistema compatible con 6 incógnitas tiene rango 4. ¿Cuántos parámetros libres necesita?',[F('Parámetros',2)],r'6−4=2 variables libres.',['Usa número de incógnitas menos rango.'])
add(4,'N','4-2','Multiplicador de Gauss',r'Para eliminar el 6 situado debajo de un pivote 2, se hace F₂←F₂−mF₁. ¿Cuánto vale m?',[F('m',3)],r'6/2=3 y 6−3·2=0.',['Resuelve 6−2m=0.'])
add(4,'N','4-3','Leer formatos QR',r'A es real 5×3, con columnas independientes. Da el formato de Q y R en la QR reducida.',[F('Formato Q',[5,3],'vector'),F('Formato R',[3,3],'vector')],r'Q conserva tres columnas ortonormales de longitud 5. R es triangular 3×3.',['Las tres columnas de A se expresan en tres direcciones ortonormales.'])
add(4,'N','4-4','Mejor constante',r'Ajusta una constante c a los datos 1,2,6 minimizando la suma de cuadrados.',[F('c',3)],r'La ecuación normal es 3c=1+2+6=9, luego c=3.',['La columna de diseño tiene tres unos.'])
add(4,'M','4-2','Reconstruir LU',r'Para A=[[3,1],[6,4]], sin permutar, calcula L y U con diagonal de L igual a uno.',[F('L',[[1,0],[2,1]],'matrix'),F('U',[[3,1],[0,2]],'matrix')],r'El multiplicador es 6/3=2. La segunda fila de U es (6,4)−2(3,1)=(0,2).',['Guarda en L el multiplicador usado.'])
add(4,'M','4-1','Una solución y su dirección',r'Resuelve x+y+z=3, y−z=1. Da una solución con z=0 y una base de las direcciones homogéneas.',[F('Particular',[2,1,0],'vector'),F('Base homogénea',[[-2,1,1]],'basis')],r'Con z=t, y=1+t y x=2−2t. La solución pedida es (2,1,0) y la dirección (−2,1,1).',['Aísla la variable libre z.'])
add(4,'M','4-3','QR sin radicales difíciles',r'A=[[3,0],[4,5]]. Usando q₁=(3/5,4/5), q₂=(−4/5,3/5), calcula R.',[F('R',[[5,4],[0,3]],'matrix')],r'r₁₁=5, r₁₂=q₁ᵀ(0,5)=4 y r₂₂=q₂ᵀ(0,5)=3. QᵀA=R.',['Multiplica Qᵀ por A.'])
add(4,'M','4-4','Un ajuste inconsistente',r'A tiene única columna (1,2), b=(1,0). Halla el coeficiente óptimo x y el residuo b−Ax.',[F('x',0.2),F('Residuo',[0.8,-0.4],'vector')],r'AᵀA=5 y Aᵀb=1, así x=1/5. El residuo (4/5,−2/5) es ortogonal a (1,2).',['Usa una ecuación normal escalar.'])
add(4,'M','4-5','Schur ya triangular',r'T=[[1,7,2],[0,−2,3],[0,0,4]] es una forma de Schur. Da autovalores, traza y determinante.',[F('Autovalores',[1,-2,4],'set'),F('Traza',3),F('Determinante',-8)],r'Los autovalores son la diagonal. La suma es 3 y el producto −8.',['La parte superior fuera de la diagonal no altera esos valores.'])
add(4,'M','4-3','Reflexión de Householder',r'Para v=(1,1), calcula H=I−2vvᵀ/(vᵀv).',[F('H',[[0,-1],[-1,0]],'matrix')],r'vᵀv=2 y vvᵀ es la matriz de unos. Al restarla de I resulta [[0,−1],[−1,0]]. H²=I.',['Forma primero el producto exterior.'])
add(4,'G','4-1','Discusión con parámetro',r'El sistema x+y=1, 2x+(a+1)y=2 tiene un valor excepcional de a. Da ese valor, clasifica el sistema en él y resuelve para a=2.',[F('a excepcional',1),F('Tipo excepcional','infinitas soluciones','choice',options=['única solución','infinitas soluciones','incompatible']),F('Solución a=2',[1,0],'vector')],r'Resta 2 veces la primera ecuación: (a−1)y=0. Si a=1 queda redundancia y x=1−y. Si a≠1, y=0 y x=1.',['No dividas por a−1 sin separar su cero.'])
add(4,'G','4-2','PLU con intercambio',r'A=[[0,2],[1,3]]. Fija P=[[0,1],[1,0]] y PA=LU con L triangular inferior y diagonal de unos. Da L,U y la solución de Ax=(4,7).',[F('L',[[1,0],[0,1]],'matrix'),F('U',[[1,3],[0,2]],'matrix'),F('x',[1,2],'vector')],r'PA=[[1,3],[0,2]] ya es triangular, por lo que L=I. Pb=(7,4); 2x₂=4 y x₁+3x₂=7, de donde (1,2).',['Permuta también el término independiente.'])
add(4,'G','4-4','Recta de mínimos cuadrados',r'Ajusta α+βt a (0,1),(1,3),(2,2). Da coeficientes y suma mínima de cuadrados de residuos.',[F('α; β',[1.5,0.5],'vector'),F('Error cuadrático mínimo',1.5)],r'Las normales son 3α+3β=6 y 3α+5β=7. β=1/2, α=3/2. Residuos (−1/2,1,−1/2); sus cuadrados suman 3/2.',['Construye la matriz de diseño con columnas 1 y t.'])
add(4,'G','4-4','No unicidad y norma mínima',r'A=[[1,1],[2,2]], b=(1,0). Da la solución de mínimos cuadrados de menor norma y una base de las direcciones de todos los minimizadores.',[F('Mínima norma',[0.1,0.1],'vector'),F('Direcciones',[[1,-1]],'basis')],r'El ajuste depende de s=x+y: minimiza (s−1)²+4s², con s=1/5. La menor norma reparte por igual, x=y=1/10. Cualquier t(1,−1) conserva el ajuste.',['Reduce primero a la variable s=x+y.'])
add(4,'G','4-3','Verificar una QR propuesta',r'Q=[[1/√2,1/√2],[1/√2,−1/√2]], R=[[√2,3/√2],[0,−1/√2]]. Calcula A=QR y decide si la factorización es válida aunque R tenga una entrada diagonal negativa.',[F('A',[[1,1],[1,2]],'matrix'),F('¿Válida?','sí','choice',options=['sí','no'])],r'QᵀQ=I y el producto da [[1,1],[1,2]]. El signo negativo no invalida una QR; solo incumple la convención adicional de diagonal positiva para unicidad.',['Validez y normalización de signos son distintas condiciones.'])
add(4,'G','4-5','Schur frente a diagonalización',r'A=[[5,1],[0,5]]. Da la dimensión del autoespacio de 5 y decide si tiene Schur compleja y si es diagonalizable.',[F('dim E₅',1),F('Schur','sí','choice',options=['sí','no']),F('Diagonalizable','no','choice',options=['sí','no'])],r'A−5I impone y=0. Solo hay una dirección propia, insuficiente para diagonalizar. Ya es triangular, así Q=I y T=A constituyen Schur.',['Calcula el núcleo de A−5I.'])
# TEMA V
add(5,'N','5-1','Potencias diagonales',r'D=diag(2,−1,3). Da la diagonal de D³.',[F('Diagonal',[8,-1,27],'vector')],r'Cada entrada se eleva al cubo: 8,−1,27.',['No cubiques toda la lista como un escalar.'])
add(5,'N','5-4','Leer inercia',r'D=diag(4,−2,0,7). Da la inercia en orden positivos, negativos, nulos.',[F('Inercia',[2,1,1],'vector')],r'4 y 7 son positivos, −2 negativo, y hay un cero.',['Cuenta signos, no sumes valores.'])
add(5,'N','5-6','Valores singulares diagonales',r'A=diag(−4,2,0). Da valores singulares en orden decreciente, incluyendo cero, y rango.',[F('Valores',[4,2,0],'vector'),F('Rango',2)],r'AᵀA=diag(16,4,0); sus raíces son 4,2,0. Dos son positivos.',['Los singulares nunca son negativos.'])
add(5,'N','5-7','Pseudoinversa diagonal',r'Calcula la pseudoinversa de diag(2,0,−4).',[F('Matriz',[[0.5,0,0],[0,0,0],[0,0,-0.25]],'matrix')],r'En esta matriz diagonal real se invierten las entradas no nulas y se conserva cero: diag(1/2,0,−1/4).',['No dividas por la entrada nula.'])
add(5,'N','5-3','Una raíz positiva',r'D=diag(9,4,0). Da la diagonal de su raíz semidefinida positiva.',[F('Diagonal',[3,2,0],'vector')],r'Raíces no negativas entrada a entrada: 3,2,0. No es definida positiva por su cero.',['La condición semidefinida positiva fija los signos.'])
add(5,'N','5-5','Un bloque de Jordan',r'J es un bloque 3×3 para λ=2. Indica multiplicidad algebraica y geométrica.',[F('Algebraica',3),F('Geométrica',1)],r'El bloque tiene tres entradas λ en la diagonal, pero una sola dirección propia.',['La geométrica cuenta bloques, no tamaño total.'])
add(5,'M','5-2','Cholesky',r'Encuentra C triangular inferior con diagonal positiva tal que [[9,3],[3,4]]=CCᵀ.',[F('C',[[3,0],[1,3**0.5]],'matrix')],r'c₁₁=3; 2c₂₁=3 implica c₂₁=1; c₂₂²=4−1=3.',['Iguala las tres entradas independientes de CCᵀ.'])
add(5,'M','5-2','La diagonal en LDU',r'A=[[2,4],[6,15]]. En A=LDU con L y U triangulares con diagonal de unos, da la diagonal de D.',[F('Diagonal',[2,3],'vector')],r'El multiplicador es 3; la segunda fila residual es (0,3). Los pivotes son 2 y 3.',['D contiene los pivotes de eliminación.'])
add(5,'M','5-3','Diagonalización espectral',r'A=[[3,1],[1,3]]. Da un autovector de norma 1 para el mayor autovalor.',[F('Vector',[2**-0.5,2**-0.5],'unitEigen',matrix=[[3,1],[1,3]],eigenvalue=4)],r'El mayor autovalor es 4 y su dirección (1,1). Al normalizar, ±(1,1)/√2. Se aceptan ambos signos.',['Usa simetría y normaliza al final.'])
add(5,'M','5-4','Criterio de Sylvester',r'S=[[a,1],[1,2]]. ¿Para qué c real es S definida positiva exactamente cuando a>c?',[F('c',0.5)],r'Los menores líderes exigen a>0 y 2a−1>0. La segunda condición implica la primera, así a>1/2.',['Combina ambas desigualdades.'])
add(5,'M','5-5','Potencia de Jordan',r'A=[[2,1],[0,2]]. Calcula A³.',[F('A³',[[8,12],[0,8]],'matrix')],r'A=2I+N, N²=0. A³=8I+12N.',['Aplica el binomio y elimina términos con N².'])
add(5,'M','5-6','Error de truncación',r'Una matriz tiene valores singulares 5,3,1. Da el error de Frobenius de su mejor aproximación de rango 1 y de rango 2.',[F('Error rango 1',10**0.5),F('Error rango 2',1)],r'Para rango 1 se descartan 3 y 1: √(9+1)=√10. Para rango 2 solo se descarta 1.',['Suma cuadrados de los valores descartados.'])
add(5,'G','5-1','Diagonalización con parámetro',r'Aₐ=[[2,a],[0,2]]. ¿Para qué a es diagonalizable? Justifica con multiplicidades.',[F('a',0)],r'El único autovalor es 2, algebraica 2. Si a≠0, su autoespacio tiene dimensión 1. Solo a=0 da A=2I y dos direcciones independientes.',['Estudia el rango de A−2I.'])
add(5,'G','5-5','Reconstruir los bloques',r'Para un único autovalor de multiplicidad algebraica 6, las nulidades de (A−λI)^k para k=1,2,3 son 3,5,6. Da los tamaños de los bloques en orden decreciente.',[F('Tamaños',[3,2,1],'vector')],r'Las diferencias 3,2,1 cuentan bloques de tamaño al menos 1,2,3. Hay un bloque de tamaño 3, uno de tamaño 2 y uno de tamaño 1. Suman 6.',['Resta nulidades consecutivas, empezando en d₀=0.'])
add(5,'G','5-4','Un falso criterio',r'S=diag(0,−2,3). Da los tres menores principales líderes y decide si es semidefinida positiva.',[F('Líderes',[0,0,0],'vector'),F('¿Semidefinida positiva?','no','choice',options=['sí','no'])],r'Todos los líderes incluyen la primera entrada cero. Sin embargo q(e₂)=−2 y q(e₃)=3; es indefinida. Los líderes no negativos no bastan.',['Busca un vector que refute la positividad.'])
add(5,'G','5-6','SVD de rango uno',r'A=[[3,4],[0,0]]. Da el único valor singular positivo, un vector singular derecho unitario correspondiente y la pseudoinversa.',[F('σ',5),F('Vector derecho',[0.6,0.8],'unitEigen',matrix=[[9,12],[12,16]],eigenvalue=25),F('A⁺',[[3/25,0],[4/25,0]],'matrix')],r'AᵀA tiene autovalores 25 y 0. Se puede tomar v=(3/5,4/5), u=(1,0). Entonces A⁺=v(1/5)uᵀ. Cambiar ambos signos conserva la SVD.',['Usa AᵀA para hallar la dirección derecha.'])
add(5,'G','5-7','Pseudoinversa y residuo',r'A=[[1,1],[0,0]], b=(4,3). Calcula el minimizador de menor norma, el residuo b−Ax y su norma.',[F('x mínimo',[2,2],'vector'),F('Residuo',[0,3],'vector'),F('Norma residual',3)],r'El mejor ajuste es (4,0), así x+y=4. La menor norma se alcanza repartiendo por igual: (2,2). El componente 3 no puede explicarse por la imagen.',['Separa proyección de b y selección de coeficientes.'])
add(5,'G','5-1','Potencia mediante semejanza',r'A=[[2,1],[0,4]]. Calcula A⁴ y justifica usando una base de autovectores.',[F('A⁴',[[16,120],[0,256]],'matrix')],r'Los autovectores son (1,0) para λ=2 y (1/2,1) para λ=4, así P=[[1,1/2],[0,1]] y D=diag(2,4). Entonces A⁴=PD⁴P⁻¹: las diagonales son 2⁴=16 y 4⁴=256, y la entrada superior derecha es (4⁴−2⁴)/2=120.',['La base propia permite elevar solo D.'])
add(1,'N','1-4','Notación científica',r'Escribe 0,004560 como s·10ᵏ con 1≤s<10. Da s, k y el número de cifras significativas de la escritura original.',[F('s',4.56),F('k',-3),F('Cifras significativas',4)],r'0,004560=4,560·10⁻³. Los ceros iniciales no cuentan y el cero final expresa precisión: cuatro cifras.',['Empieza a contar en el primer dígito no nulo.'])
add(1,'M','1-4','Mantisa binaria limitada',r'El modelo binario guarda cuatro cifras significativas de mantisa. Redondea el valor exacto (1.1011)₂·2³ al más cercano con empate al par. Da primero el valor exacto y luego el redondeado en decimal.',[F('Exacto',13.5),F('Redondeado',14)],r'La mantisa exacta vale 1+1/2+1/8+1/16=1,6875; multiplicada por 8 da 13,5. Los vecinos de cuatro cifras son 13 y 14; la última cifra binaria de 14 es par (0).',['Los vecinos de cuatro cifras son (1.101)₂·2³ y (1.110)₂·2³.'])
add(2,'M','2-4','Contraer un tensor',r'T tiene dos cortes T₁=[[1,2],[0,1]] y T₂=[[0,1],[−1,0]]. Con u=(1,2), v=(3,1), calcula wₖ=Σᵢⱼ Tₖᵢⱼ uᵢvⱼ.',[F('w',[7,-5],'vector')],r'Para k=1: 1·1·3+2·1·1+0·2·3+1·2·1=7. Para k=2: 0+1·1·1−1·2·3+0=−5.',['Contrae cada corte como uᵀTₖv.'])
add(2,'G','2-3','Antisimetría de tres índices',r'T es antisimétrico de tres ejes de longitud 3 y T₁₂₃=5. Calcula T₂₁₃, T₃₁₂ y T₁₁₂.',[F('T₂₁₃',-5),F('T₃₁₂',5),F('T₁₁₂',0)],r'Intercambiar 1 y 2 cambia signo. (3,1,2) es una permutación par, con dos intercambios: conserva signo. Dos índices iguales fuerzan cero.',['Cuenta paridad de intercambios y comprueba índices repetidos.'])
add(3,'M','3-6','Reducir una potencia',r'A es 2×2 con traza 4 y determinante 3. Por Cayley–Hamilton, escribe A³=αA+βI. Da α y β.',[F('α;β',[13,-12],'vector')],r'A²=4A−3I. Multiplica por A y sustituye: A³=4(4A−3I)−3A=13A−12I.',['La constante del polinomio multiplica a I.'])
add(3,'G','3-6','Una inversa sin Gauss',r'A=[[4,1],[2,1]]. Usa Cayley–Hamilton para calcular A⁻¹ y compruébala por multiplicación.',[F('A⁻¹',[[0.5,-0.5],[-1,2]],'matrix')],r'Traza 5, determinante 2. La identidad A²−5A+2I=0 da A⁻¹=(5I−A)/2=[[1/2,−1/2],[−1,2]].',['Multiplica la identidad por la inversa y despeja.'])
add(4,'G','4-3','QR adaptada al rango',r'A=[[1,2,4],[0,0,0]], b=(5,2). Da una Qᵣ con una columna ortonormal que genere la imagen (como un vector), el minimizador de menor norma y la norma del residuo.',[F('Columna Qᵣ',[1,0],'unitSpan',matrix=[[1,2,4],[0,0,0]]),F('x mínimo',[5/21,10/21,20/21],'vector'),F('Norma residual',2)],r'Puede elegirse Qᵣ=e₁ y Rᵣ=(1 2 4). El mejor ajuste exige x₁+2x₂+4x₃=5. La solución mínima reparte 5 entre los coeficientes de (1,2,4) en proporción inversa a sus cuadrados: (5/21)(1,2,4)=(5/21,10/21,20/21). Residuo (0,2).',['Proyecta b sobre la imagen y reparte la solución en la dirección fila.'])
# Cobertura por lección: se completa cada nivel ausente y se suben a tres las lecciones pobres.
add(1,'M','1-1','Unión, intersección y producto',r'A={1,2,3} y B={2,3,4}. Da A∩B, A∪B y el cardinal de A×B. Los elementos de un conjunto se separan con punto y coma.',[F('A ∩ B',[2,3],'set'),F('A ∪ B',[1,2,3,4],'set'),F('|A × B|',12)],r'Los comunes son 2 y 3; la unión tiene cuatro elementos. Cada uno de los 3 elementos de A se empareja con cada uno de los 4 de B: 3·4=12.',['Une primero y cuenta después.'])
add(1,'G','1-1','Dominio y rango de una relación',r'R={(1,2),(2,3)} es una relación sobre {1,2,3}. Da el dominio, el rango y el cardinal de A×A con A={1,2,3}.',[F('Dominio',[1,2],'set'),F('Rango',[2,3],'set'),F('|A × A|',9)],r'Dominio y rango son las primeras y las segundas coordenadas. Una relación sobre A es un subconjunto de A×A, que tiene 3·3=9 pares.',['El rango son las segundas coordenadas.'])
add(1,'N','1-2','Composición e inversa',r'Para f(x)=2x+1, calcula f(f(0)) y f⁻¹(5).',[F('f(f(0))',3),F('f⁻¹(5)',2)],r'f(f(0))=f(1)=3. Para deshacer 2x+1=5 despejamos x=2.',['La composición se aplica de dentro afuera.'])
add(2,'M','2-1','Dependencias en una familia',r'Considera (1,1,2), (1,0,1) y (2,1,3) en ℝ³. Da el rango de la familia y una base de su núcleo.',[F('Rango',2),F('Base del núcleo',[[-1,-1,1]],'basis')],r'El tercero es la suma de los dos primeros: (1,1,2)+(1,0,1)=(2,1,3). Esa es la relación no trivial v₁+v₂−v₃=0, de modo que el rango es 2 y el núcleo es la recta de (−1,−1,1).',['Busca una combinación no trivial que dé cero.'])
add(2,'M','2-3','Trasponer y adjuntar',r'Para A=[[1,i],[2,3]], da Aᵀ y A*. Como hay entradas complejas, escribe de cada matriz la parte real y la parte imaginaria, con una fila por línea y componentes separadas por punto y coma.',[F('Aᵀ (parte real)',[[1,2],[0,3]],'matrix'),F('Aᵀ (parte imaginaria)',[[0,0],[1,0]],'matrix'),F('A* (parte real)',[[1,2],[0,3]],'matrix'),F('A* (parte imaginaria)',[[0,0],[-1,0]],'matrix')],r'Trasponer intercambia filas y columnas sin conjugar: Aᵀ=[[1,2],[i,3]]. La adjunta además conjuga, así que A*=[[1,2],[−i,3]]. Solo difieren en la posición (2,1), donde la imaginaria pasa de 1 a −1.',['Sobre reales coinciden; aquí no.'])
add(2,'G','2-4','Adjoint of a product',r'A=[[1,2],[0,1]] y B=[[2,0],[1,3]]. Calcula (AB)*.',[F('(AB)*',[[4,1],[6,3]],'matrix')],r'AB=[[4,6],[1,3]], y su adjunta es [[4,1],[6,3]]. Comprueba que coincide con B*A*: el orden se invierte.',['Conmuta el orden de los factores.'])
add(2,'G','2-6','Ortogonalidad y Pitágoras',r'u=(1,2) y v=(2,−1) en ℝ². Comprueba que son ortogonales, calcula sus normas y el producto escalar.',[F('u*v',0),F('‖u‖',5**0.5),F('‖v‖',5**0.5),F('‖u+v‖',10**0.5)],r'uᵀv=1·2+2·(−1)=0, luego son ortogonales. Ambas normas valen √5 y ‖u+v‖=‖(3,1)‖=√10, que coincide con √(5+5) por el teorema de Pitágoras.',['Multiplica antes de comparar.'])
add(2,'N','2-7','Normalizar un vector',r'Normaliza u=(1,2,2) a longitud 1.',[F('Vector unitario',[1/3,2/3,2/3],'vector')],r'‖u‖=√(1+4+4)=3, así que el vector unitario es (1/3,2/3,2/3).',['Divide cada componente por la norma.'])
add(2,'N','2-8','Proyectar sobre una recta',r'Proyecta b=(2,4) sobre la recta generada por u=(1,1) y calcula la distancia.',[F('Proyección',[3,3],'vector'),F('Distancia',2**0.5)],r'El coeficiente es (uᵀb)/(uᵀu)=6/2=3, luego p=(3,3). El residuo (−1,1) tiene norma √2.',['La distancia es la norma del residuo.'])
add(3,'M','3-1','Construir la matriz con imágenes',r'f(x,y)=(2x−y,x+3y). Escribe su matriz canónica y calcula f(1,1).',[F('Matriz',[[2,-1],[1,3]],'matrix'),F('f(1;1)',[1,4],'vector')],r'f(e₁)=(2,1) y f(e₂)=(−1,3) son las columnas. Luego f(1,1)=(1,4).',['Las imágenes de la base van en columnas.'])
add(3,'N','3-6','La traza y el determinante bastan',r'Una matriz 2×2 tiene traza 7 y determinante 10. Por Cayley–Hamilton, escribe A²=αA+βI. Da α y β.',[F('α;β',[7,-10],'vector')],r'El polinomio característico es t²−7t+10, de modo que A²=7A−10I: α=7 y β=−10.',['El coeficiente de A es la traza con signo cambiado.'])
add(4,'N','4-5','Leer una triangular',r'A=[[2,1,0],[0,3,4],[0,0,1]] es triangular superior. Da sus autovalores, su traza y su determinante.',[F('Autovalores',[1,2,3],'set'),F('Traza',6),F('Determinante',6)],r'Los autovalores de una triangular son su diagonal: 2, 3 y 1. La traza es 2+3+1=6 y el determinante 2·3·1=6.',['La diagonal contiene todo el espectro.'])
add(5,'M','5-1','Similitud o congruencia',r'S=diag(2,5) y C=diag(3,1). Calcula CᵀSC, que es una congruencia, y explica por qué no es una similitud.',[F('CᵀSC',[[18,0],[0,5]],'matrix')],r'CᵀSC=diag(18,5). Por congruencia cambian las entradas de la forma: los autovalores 2 y 5 no se conservan. Por similitud se conservarían, y CᵀSC no es semejante a S.',['La congruencia no conserva los valores concretos.'])
add(5,'N','5-2','El multiplicador de eliminación',r'Para A=[[6,3],[3,5]], el multiplicador para anular la entrada 3 situada bajo el pivote 6 es m. Da m y la fila residual.',[F('m',1/2),F('Fila residual',[0,7/2],'vector')],r'm=3/6=1/2. La segunda fila residual es (3,5)−(1/2)(6,3)=(0,7/2).',['Guarda el multiplicador, no el negativo.'])
add(5,'G','5-2','LDL* y Cholesky',r'A=[[4,1],[1,3]] es hermítica definida positiva. Da la factorización A=LDL* con D diagonal y, en consecuencia, un factor C con A=CC*.',[F('D',[[4,0],[0,11/4]],'matrix'),F('C',[[2,0],[1/2,(11**0.5)/2]],'matrix')],r'El multiplicador es 1/4 y el segundo pivote 3−1/4=11/4, así D=diag(4,11/4) y L=[[1,0],[1/4,1]]. Tomando C=LD^{1/2} se obtiene C=[[2,0],[1/2,√11/2]], y CC*=A.',['C=LD^{1/2}: raíces de los pivotes de D.'])
add(5,'G','5-3','Raíz cuadrada de una hermítica',r'Para A=[[5,1],[1,5]], da la raíz cuadrada semidefinida positiva A^{1/2}.',[F('A^{1/2}',[[1+6**0.5/2,(6**0.5-2)/2],[(6**0.5-2)/2,1+6**0.5/2]],'matrix')],r'Los autovalores son 6 y 4, con direcciones (1,1) y (1,−1). Así A^{1/2}=Q diag(√6,2)Qᵀ, que da la matriz indicada. Comprueba que su cuadrado es A.',['Eleva a la mitad en la diagonal de D.'])
add(5,'M','5-7','Ajuste con rango deficiente',r'A=[[1,1],[1,1]] y b=(2,4). Da la pseudoinversa, el minimizador de menor norma, el residuo y su norma.',[F('A⁺',[[0.25,0.25],[0.25,0.25]],'matrix'),F('x mínimo',[1.5,1.5],'vector'),F('Residuo',[-1,1],'vector'),F('Norma residual',2**0.5)],r'A=[[1,1],[1,1]] se escribe u vᵀ con u=v=(1,1)ᵀ, y de ahí A⁺=v uᵀ/(‖u‖²‖v‖²)=(1/4)[[1,1],[1,1]]. Aquí A no tiene filas independientes, así que la fórmula A⁺=A*(AA*)⁻¹ no se puede aplicar. El ajuste es (3,3) y el residuo (−1,1) tiene norma √2.',['Separa proyección y selección de coeficientes.'])
add(5,'N','5-3','Autovalores de una simétrica',r'Para A=[[5,1],[1,5]], da el conjunto de autovalores.',[F('Autovalores',[4,6],'set')],r'det(A−λI)=(5−λ)²−1=(λ−4)(λ−6).',['Factoriza una diferencia de cuadrados.'])

# Exámenes distintos de la práctica; dos preguntas por dificultad.
def exam(id,title,topics,minutes,items):
 for j,(lev,prompt,fields,solution) in enumerate(items,1):
  E.append(dict(id=f'{id}-{j}',exam=id,topic=topics[-1],level=lev,lesson='',title=f'Pregunta {j}',prompt=prompt,fields=fields,solution=solution,hints=[],rubric=['Planteamiento e hipótesis: 2 puntos.','Método y desarrollo justificados: 5 puntos.','Resultados y comprobación: 3 puntos.']))
 return dict(id=id,title=title,topics=topics,minutes=minutes,questions=[f'{id}-{j}' for j in range(1,len(items)+1)])
X=[]
X.append(exam('e12','Examen I · Escalares y estructura',[1,2],90,[
('N',r'Convierte $(10111)_2$ a decimal y calcula el módulo de 5−12i.',[F('Decimal',23),F('Módulo',13)],r'16+4+2+1=23; √(25+144)=13.'),
('N',r'A=[[1,2],[3,1]], x=(2,−1). Calcula Ax y la entrada (1,1) de A⁻¹.',[F('Ax',[0,5],'vector'),F('Entrada (1,1) de A⁻¹',-0.2)],r'Ax=(2−2,6−1)=(0,5). La fórmula 2×2 de la inversa da la entrada 1/(1−6)=−1/5.'),
('M',r'Calcula (2−i)/(1+2i) y las coordenadas de (4,2) en B=((1,1),(1,−1)).',[F('Cociente real; imaginaria',[0,-1],'vector'),F('Coordenadas',[3,1],'vector')],r'El cociente es −i porque (−i)(1+2i)=2−i. Las coordenadas resuelven a+b=4,a−b=2: (3,1).'),
('M',r'Proyecta (1,2,3) sobre la recta generada por (1,1,1). Da la distancia.',[F('Proyección',[2,2,2],'vector'),F('Distancia',2**0.5)],r'Coeficiente 6/3=2; residuo (−1,0,1), norma √2.'),
('G',r'Para z³=−8, da módulo y argumentos en [0,2π) como coeficientes de π. Justifica que no faltan raíces.',[F('Módulo',2),F('Coeficientes',[1/3,1,5/3],'set')],r'−8=8e^{iπ}. Módulo 2 y argumentos (π+2kπ)/3 para k=0,1,2: π/3,π,5π/3; son tres raíces distintas.'),
('G',r'En ℝ³, S={x−y+z=0}. Da una base de S y proyecta b=(2,0,1) sobre S.',[F('Base',[[1,1,0],[-1,0,1]],'basis'),F('Proyección',[1,1,0],'vector')],r'Normal n=(1,−1,1), nᵀb=3 y nᵀn=3. Proyección b−n=(1,1,0). Los dos vectores dados satisfacen la ecuación y son independientes.')]))
X.append(exam('e34','Examen II · Aplicaciones y sistemas',[3,4],100,[
('N',r'A tiene formato 3×5 y rango 2. Da las nulidades de A y A*.',[F('Nulidad A',3),F('Nulidad A*',1)],r'5−2=3 y 3−2=1.'),
('N',r'Resuelve 2x−y=1, 3y=9 y calcula el determinante de su matriz.',[F('x;y',[2,3],'vector'),F('Determinante',6)],r'y=3, x=2. Matriz triangular con producto de diagonal 6.'),
('M',r'A=[[1,2,3],[0,1,2]]. Da una base del núcleo y el rango.',[F('Base',[[1,-2,1]],'basis'),F('Rango',2)],r'y=−2z, x=z. Dos pivotes y núcleo de dimensión 1.'),
('M',r'Factoriza A=[[2,2],[6,8]]=LU con diagonal de L unitaria.',[F('L',[[1,0],[3,1]],'matrix'),F('U',[[2,2],[0,2]],'matrix')],r'Multiplicador 3; la segunda fila residual es (0,2). Comprueba LU=A.'),
('G',r'Ajusta α+βt a (0,0),(1,2),(2,1). Da coeficientes y suma de cuadrados residual.',[F('α;β',[0.5,0.5],'vector'),F('Suma residual',1.5)],r'Normales: 3α+3β=3,3α+5β=4. Da α=β=1/2. Residuo (−1/2,1,−1/2), cuadrados suman 3/2.'),
('G',r'Aₐ=[[1,1],[2,a]], b=(1,3). Discute el valor excepcional de a y da la solución para a=3.',[F('a excepcional',2),F('Tipo excepcional','incompatible','choice',options=['única solución','infinitas soluciones','incompatible']),F('Solución a=3',[0,1],'vector')],r'Restar 2 veces la primera ecuación da (a−2)y=1. Si a=2 es imposible. Si a=3, y=1,x=0.')]))
X.append(exam('e5','Examen III · Diagonalización y síntesis',[5],100,[
('N',r'A=diag(−3,0,2). Da su rango y sus valores singulares en orden decreciente.',[F('Rango',2),F('Valores',[3,2,0],'vector')],r'Dos entradas no nulas. Los singulares son los módulos ordenados.'),
('N',r'Una hermítica tiene autovalores −2,−1,0,4. Da su inercia y clasifícala.',[F('Inercia',[1,2,1],'vector'),F('Clasificación','indefinida','choice',options=['definida positiva','semidefinida positiva','indefinida'])],r'Toma signos positivos y negativos: indefinida. Inercia (1,2,1).'),
('M',r'Calcula la Cholesky con diagonal positiva de [[9,3],[3,2]].',[F('C',[[3,0],[1,1]],'matrix')],r'c₁₁=3, c₂₁=1, c₂₂=√(2−1)=1.'),
('M',r'J=[[3,1],[0,3]]. Calcula J² y la dimensión de su autoespacio.',[F('J²',[[9,6],[0,9]],'matrix'),F('Dimensión',1)],r'J=3I+N, N²=0, así J²=9I+6N. El autoespacio es span e₁.'),
('G',r'A=[[2,0,0],[0,0,0]], b=(6,5). Da la pseudoinversa, el minimizador de menor norma y la norma del residuo.',[F('A⁺',[[0.5,0],[0,0],[0,0]],'matrix'),F('x mínimo',[3,0,0],'vector'),F('Norma residual',5)],r'Solo se invierte el valor 2. x=(3,0,0) da Ax=(6,0), residuo (0,5); variables libres deben ser cero para mínima norma.'),
('G',r'Para λ único de multiplicidad 5, nulidades de potencias de A−λI: 2,4,5. Da tamaños Jordan. Si una matriz tiene singulares 6,2,1, da su error Frobenius al truncar a rango 1.',[F('Bloques',[3,2],'vector'),F('Error',5**0.5)],r'Con d₀=0, las diferencias d₁−d₀=2, d₂−d₁=2 y d₃−d₂=1 cuentan los bloques de tamaño ≥1, ≥2 y ≥3: hay un bloque de tamaño 3 y uno de tamaño 2, que suman 5. El error de truncación a rango 1 es √(2²+1²)=√5.')]))
X.append(exam('sim','Simulacro · Cuatro preguntas de desarrollo',[1,2,3,4,5],120,[
('G',r'1. Resuelve z⁴=1: da las cuatro raíces como pares real/imaginaria (una fila por raíz, en cualquier orden). Calcula además (1−i)⁶ y explica el uso de la forma polar.',[F('Raíces',[[1,0],[0,1],[-1,0],[0,-1]],'rowsSet'),F('Potencia real; imaginaria',[0,8],'vector')],r'Las raíces son e^{ikπ/2}, k=0,1,2,3: 1,i,−1,−i. (1−i)⁶=(√2)⁶e^{-3πi/2}=8i.'),
('G',r'2. S={x+y+z=0}. Da una base, la matriz de proyección ortogonal y la proyección de (3,0,0). Justifica ortogonalidad del residuo.',[F('Base',[[1,-1,0],[1,0,-1]],'basis'),F('P',[[2/3,-1/3,-1/3],[-1/3,2/3,-1/3],[-1/3,-1/3,2/3]],'matrix'),F('Proyección',[2,-1,-1],'vector')],r'Normal n=(1,1,1); P=I−nnᵀ/3. Aplicar a b da (2,−1,−1); residuo (1,1,1) es perpendicular al plano. Los vectores base son LI y satisfacen la ecuación.'),
('G',r'3. A=[[1,0],[1,1],[1,2]], b=(1,0,2). Plantea normales, encuentra el minimizador y calcula norma residual. Explica por qué es único.',[F('AᵀA',[[3,3],[3,5]],'matrix'),F('x óptimo',[0.5,0.5],'vector'),F('Norma residual',1.5**0.5)],r'Aᵀb=(3,4), así x=(1/2,1/2). Ajuste (1/2,1,3/2), residuo (1/2,−1,1/2), norma √(3/2). Las columnas son LI y AᵀA es definida positiva: mínimo único.'),
('G',r'4. A=[[2,1],[1,2]]. Da autovalores en orden decreciente, una matriz Q ortogonal que diagonalice A y la matriz inversa. Justifica positividad y relación con SVD.',[F('Autovalores',[3,1],'vector'),F('Q',[[2**-0.5,2**-0.5],[2**-0.5,-2**-0.5]],'spectral',matrix=[[2,1],[1,2]],diagonal=[3,1]),F('Inversa',[[2/3,-1/3],[-1/3,2/3]],'matrix')],r'Autovalores 3 y 1 con direcciones (1,1) y (1,−1). Al normalizar se obtiene Q. A⁻¹=Q diag(1/3,1)Qᵀ=(1/3)[[2,−1],[−1,2]]. Es definida positiva; su diagonalización espectral es una SVD con U=V=Q.')]))
Path('assets/exercises.js').write_text('window.EXERCISES = '+json.dumps(E,ensure_ascii=False,indent=2)+';\nwindow.EXAMS = '+json.dumps(X,ensure_ascii=False,indent=2)+';\n')
print(len(E),'ejercicios;',len(X),'evaluaciones;',sum(len(x['fields']) for x in E),'respuestas verificables')
